const docs = [];
for (const item of $input.all()) {
  if (item.json.extracted_text && item.json.status === 'success') {
    docs.push(item.json.extracted_text);
  }
}
return [{ json: { extracted_documents: docs, has_documents: docs.length > 0 } }];

function jsonToSlideDocText(data) {
  if (!data || typeof data !== "object") throw new Error("Expected an object as input.");

  const metadata = data.metadata || {};
  const rawSlides = data.slides || [];
  const slidesObj = Array.isArray(rawSlides)
    ? rawSlides.reduce((acc, s) => { acc["slide_" + String(s.slide_id || "").replace(".", "_")] = s; return acc; }, {})
    : rawSlides;

  const lines = [];

  // ---------- Helpers ----------
  const titleCaseFromKey = (key) =>
    String(key)
      .replace(/_/g, " ")
      .replace(/\s+/g, " ")
      .trim()
      .replace(/\b\w/g, (c) => c.toUpperCase());

  const isNonEmptyString = (v) => typeof v === "string" && v.trim().length > 0;
  const isNonEmptyArray = (v) => Array.isArray(v) && v.length > 0;

  const parseSlideId = (id) => {
    const raw = String(id ?? "").trim();
    if (!raw) return { major: Number.MAX_SAFE_INTEGER, minor: Number.MAX_SAFE_INTEGER, raw: "" };

    const parts = raw.split(".").map((p) => p.trim());
    const major = Number(parts[0]);
    const minor = parts.length > 1 ? Number(parts[1]) : 0;

    return {
      major: Number.isFinite(major) ? major : Number.MAX_SAFE_INTEGER,
      minor: Number.isFinite(minor) ? minor : Number.MAX_SAFE_INTEGER,
      raw,
    };
  };

  const compareSlide = (a, b) => {
    const pa = parseSlideId(a.slide_id);
    const pb = parseSlideId(b.slide_id);
    if (pa.major !== pb.major) return pa.major - pb.major;
    if (pa.minor !== pb.minor) return pa.minor - pb.minor;
    return String(pa.raw).localeCompare(String(pb.raw));
  };

  const hr = () => lines.push("──────────────────────────────────────────────");

  const h0 = (t) => {
    lines.push(String(t));
    lines.push("=".repeat(Math.max(8, String(t).length)));
  };

  const h1 = (t) => {
    lines.push(String(t));
    lines.push("-".repeat(Math.max(6, String(t).length)));
  };

  const h2 = (t) => {
    lines.push(String(t).toUpperCase());
  };

  const addBlank = () => lines.push("");

  const renderList = (items, indent = "") => {
    return items.map((x) => `${indent}• ${String(x)}`);
  };

  const renderAnyValueAsList = (value) => {
    if (isNonEmptyArray(value)) return value.map((x) => String(x));
    if (isNonEmptyString(value)) return [value.trim()];
    if (value && typeof value === "object") {
      const out = [];
      for (const [k, v] of Object.entries(value)) {
        if (isNonEmptyArray(v)) out.push(`${titleCaseFromKey(k)}: ${v.join("; ")}`);
        else if (isNonEmptyString(v)) out.push(`${titleCaseFromKey(k)}: ${v.trim()}`);
      }
      return out;
    }
    return [];
  };

  // ---------- Deck Title ----------
  const deckTitle = isNonEmptyString(metadata.project_name)
    ? metadata.project_name.trim()
    : "SLIDE DECK";

  h0(deckTitle);
  addBlank();

  // ---------- Cover meta ----------
  const coverMeta = [];
  if (isNonEmptyString(metadata.client_name)) coverMeta.push(`Client: ${metadata.client_name.trim()}`);
  if (isNonEmptyString(metadata.generated_date)) coverMeta.push(`Generated: ${metadata.generated_date.trim()}`);
  if (metadata.total_slides != null && String(metadata.total_slides).trim() !== "")
    coverMeta.push(`Total Slides: ${String(metadata.total_slides).trim()}`);
  if (isNonEmptyString(metadata.overall_confidence))
    coverMeta.push(`Overall Confidence: ${metadata.overall_confidence.trim()}`);

  if (coverMeta.length) {
    h1("Cover");
    lines.push(...renderList(coverMeta));
    addBlank();
  }

  if (isNonEmptyString(metadata.generation_notes)) {
    h1("Generation Notes");
    lines.push(metadata.generation_notes.trim());
    addBlank();
  }

  hr();
  addBlank();

  // ---------- Slides ----------
  const slides = Object.values(slidesObj).filter((s) => s && typeof s === "object").sort(compareSlide);

  const grouped = new Map();
  for (const s of slides) {
    const { major } = parseSlideId(s.slide_id);
    if (!grouped.has(major)) grouped.set(major, []);
    grouped.get(major).push(s);
  }

  const sectionTitle = (major) => `SECTION ${major}`;

  for (const [major, sectionSlides] of grouped.entries()) {
    h0(sectionTitle(major));
    addBlank();

    sectionSlides.forEach((slide) => {
      const sid = String(slide.slide_id ?? "").trim();
      const title = String(slide.slide_title ?? `Slide ${sid || ""}`).trim();
      const templateRef = slide.template_reference ? String(slide.template_reference).trim() : "";
      const conf = slide.confidence ? String(slide.confidence).trim() : "";

      h1(`Slide ${sid} — ${title}`);
      if (templateRef || conf) {
        const metaBits = [];
        if (templateRef) metaBits.push(`Template ${templateRef}`);
        if (conf) metaBits.push(`Confidence: ${conf}`);
        lines.push(metaBits.join(" | "));
        addBlank();
      }

      const bullets = slide.bullets || {};
      if (bullets && typeof bullets === "object") {
        for (const [k, v] of Object.entries(bullets)) {
          const list = renderAnyValueAsList(v);
          if (!list.length) continue;

          h2(titleCaseFromKey(k));
          lines.push(...renderList(list));
          addBlank();
        }
      }

      const notes = slide.consultant_notes || {};
      const hasNotes =
        (notes && typeof notes === "object" && Object.keys(notes).length > 0) ||
        isNonEmptyString(notes?.walkthrough_tip);

      if (hasNotes) {
        const noteBlocks = [];

        if (isNonEmptyString(notes.walkthrough_tip)) {
          noteBlocks.push({ label: "Walkthrough Tip", items: [notes.walkthrough_tip.trim()] });
        }

        const arrays = [
          ["Slide Notes", notes.slide_notes],
          ["Gaps / Open Questions", notes.gaps],
          ["Conflicts", notes.conflicts],
          ["Ambiguity", notes.ambiguity],
        ];

        for (const [label, val] of arrays) {
          const list = renderAnyValueAsList(val);
          if (list.length) noteBlocks.push({ label, items: list });
        }

        if (noteBlocks.length) {
          h2("Presenter Notes");
          for (const block of noteBlocks) {
            lines.push(`${block.label}:`);
            lines.push(...renderList(block.items, "  "));
          }
          addBlank();
        }
      }

      hr();
      addBlank();
    });
  }

  return lines.join("\n");
}

// Main logic — LLM sub-workflow returns { llm_response: <parsed JSON object> }
// The sub-workflow's "Parse JSON Response" already handles JSON extraction and repair.
const webhook = $('1.1_TRG_Webhook').first().json.body;
const jsonData = $input.first().json.llm_response;

if (!jsonData || typeof jsonData !== 'object') {
  return [{
    "status": "error",
    "error_message": "No valid LLM response received. Expected llm_response object.",
    "client_id": webhook.client_id,
    "client_name": webhook.client_name,
    "project_id": webhook.project_id,
    "project_name": webhook.project_name,
    "workflow_id": webhook.workflow_id,
    "workflow_name": webhook.workflow_name,
    "workflow_session_id": webhook.workflow_session_id,
    "workflow_session_name": webhook.workflow_session_name
  }];
}

try {
  var content = jsonToSlideDocText(jsonData);

  return [{
    "status": "processed",
    "agent_response": (function() {
      const slides = jsonData.slides;
      const keyedSlides = Array.isArray(slides)
        ? slides.reduce((acc, s) => { acc["slide_" + String(s.slide_id || "").replace(".", "_")] = s; return acc; }, {})
        : slides;
      return { metadata: jsonData.metadata, slides: keyedSlides };
    })(),
    "content": content,
    "google_drive_folder_id": webhook.google_drive_folder_id,
    "client_id": webhook.client_id,
    "client_name": webhook.client_name,
    "project_id": webhook.project_id,
    "project_name": webhook.project_name,
    "workflow_id": webhook.workflow_id,
    "workflow_name": webhook.workflow_name,
    "workflow_session_id": webhook.workflow_session_id,
    "workflow_session_name": webhook.workflow_session_name
  }];

} catch(renderError) {
  return [{
    "status": "error",
    "error_message": "Rendering failed: " + renderError.message,
    "agent_response": jsonData,
    "client_id": webhook.client_id,
    "client_name": webhook.client_name,
    "project_id": webhook.project_id,
    "project_name": webhook.project_name,
    "workflow_id": webhook.workflow_id,
    "workflow_name": webhook.workflow_name,
    "workflow_session_id": webhook.workflow_session_id,
    "workflow_session_name": webhook.workflow_session_name
  }];
}

// Centralized error formatter
const input = $input.first().json;

function safeErrorExtract(error) {
  if (!error) return null;
  if (error instanceof Error || error.message) {
    return {
      message: error.message || 'Unknown error',
      name: error.name,
      stack: error.stack,
      ...Object.keys(error).reduce((acc, key) => {
        try { acc[key] = error[key]; } catch (e) {}
        return acc;
      }, {})
    };
  }
  return error;
}

const errorInfo = safeErrorExtract(input);

return [{
  json: {
    status: 'error',
    error_message: errorInfo?.message || input?.error_message || input?.body_error || 'Workflow execution failed',
    workflow_session_id: $('1.1_TRG_Webhook').first().json.body.workflow_session_id,
    timestamp: new Date().toISOString()
  }
}];
